test.config:
indexer
{
	mem_limit = 16M
}
searchd
{

}
source test
{
	type = mysql

	sql_query = SELECT * FROM test_table
}
index star
{
	source = test
	path = /star
	blend_chars = @, ., !, (, ), [, ], {, }
	min_infix_len = 2
	dict = crc
}

test.db_create:
CREATE TABLE test_table
(
	document_id INT NOT NULL,
	text VARCHAR(255) NOT NULL
);

test.db_insert:
INSERT INTO test_table VALUES
( 1, 'aaa bbb@ccc ddd @eee fff@ggg@hhh iii@ kkk' ),
( 2, 'ggg@hhh' );
